const cart = [];

function addToCart(item) {
  cart.push(item);

  document.querySelector("#cart-count").textContent = cart.length;
  document.querySelector("#cart-list").append(itemRow(item));
  document.querySelector("#cart-total").textContent = formatPrice(total(cart));
  document.querySelector("#checkout").disabled = cart.length === 0;
}

function removeFromCart(id) {
  const index = cart.findIndex((item) => item.id === id);
  cart.splice(index, 1);

  document.querySelector("#cart-count").textContent = cart.length;
  document.querySelector(`#cart-list [data-id="${id}"]`).remove();
  document.querySelector("#cart-total").textContent = formatPrice(total(cart));
}

:root {
  --color-accent: oklch(0.55 0.2 260);
  --color-accent-hover: oklch(0.48 0.2 260);
  --radius: 0.5rem;
  --space-2: 0.5rem;
  --space-4: 1rem;
}

.button {
  padding: var(--space-2) var(--space-4);
  border: 0;
  border-radius: var(--radius);
  background: var(--color-accent);
  color: white;
  font-weight: 600;

  &:hover {
    background: var(--color-accent-hover);
  }

  &:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }
}

